const r = ($input.first().json.results || [])[0];
if (!r) return [{ json: { found: false } }];
const basic = r.basic || {};
const loc = (r.addresses || []).find(a => a.address_purpose === 'LOCATION') || (r.addresses || [])[0] || {};
const fmtPhone = (p) => {
  const d = String(p || '').replace(/\D/g, '');
  return d.length === 10 ? `(${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}` : String(p || '');
};
const zip = String(loc.postal_code || '');
const zip5 = zip.length > 5 ? zip.slice(0, 5) : zip;
const street = [loc.address_1, loc.address_2].filter(Boolean).join(' ');
const title = (s) => String(s || '').toLowerCase().replace(/\b([a-z])/g, (m) => m.toUpperCase()).replace(/\b(Nw|Ne|Sw|Se|Llc|Inc|Pa|Ste)\b/g, (m) => ({Nw:'NW',Ne:'NE',Sw:'SW',Se:'SE',Llc:'LLC',Inc:'Inc',Pa:'PA',Ste:'Ste'})[m]);
const dba = (r.other_names || []).find(o => String(o.code) === '3' || /doing business/i.test(String(o.type || '')));
const tax = (r.taxonomies || []).find(t => t.primary) || (r.taxonomies || [])[0] || {};
return [{ json: {
  found: true,
  npi: String(r.number || ''),
  enumeration_type: r.enumeration_type || '',
  legal_name: basic.organization_name || [basic.first_name, basic.last_name].filter(Boolean).join(' '),
  dba_name: dba ? dba.organization_name : '',
  address: street ? `${title(street)}, ${title(loc.city)}, ${loc.state || ''} ${zip5}`.trim() : '',
  phone: fmtPhone(loc.telephone_number),
  fax: fmtPhone(loc.fax_number),
  taxonomy: tax.desc || '',
  status: basic.status || ''
} }];
